        mid = (l + r) // 2
        self.build(arr, 2 * node + 1, l, mid)
        self.build(arr, 2 * node + 2, mid + 1, r)
        self.tree[node] = min(self.tree[2 * node + 1], self.tree[2 * node + 2])

