          language: 'python',
          code: `from collections import deque

maze = [
    "S..#.",
    "##.#.",
    ".....",
    ".###.",
    "....E",
]
rows = len(maze)
cols = len(maze[0])
start = (0, 0)
end = (4, 4)
queue = deque([start])
parent = {start: None}
while queue:
    r, c = queue.popleft()
    if (r, c) == end:
        break
    for dr, dc in [(0, 1), (1, 0), (0, -1), (-1, 0)]:
        nr, nc = r + dr, c + dc
        if 0 <= nr < rows and 0 <= nc < cols:
            if maze[nr][nc] != "#" and (nr, nc) not in parent:
                parent[(nr, nc)] = (r, c)
                queue.append((nr, nc))
path = []
cell = end
while cell is not None:
    path.append(cell)
    cell = parent[cell]
path.reverse()
print("Steps:", len(path) - 1)
print("Path:", path)
grid = [list(row) for row in maze]
for r, c in path[1:-1]:
    grid[r][c] = "*"
for row in grid:
    print("".join(row))`,
